import { Component, OnInit } from '@angular/core';
import { OrderTrackerService } from '../../services/order-tracker.service';
import { AuthService } from '../../services/auth.service';
import { OrderTrack } from '../../Modals/EkartModels';

@Component({
  selector: 'app-order-tracker',
  templateUrl: './order-tracker.component.html',
  styleUrls: ['./order-tracker.component.css']
})
export class OrderTrackerComponent implements OnInit {
  activeTab: 'search' | 'my-orders' | 'admin-panel' = 'search';

  searchOrderId = '';
  loading = false;
  orderData: OrderTrack | null = null;
  errorMessage = '';

  userOrders: OrderTrack[] = [];
  userOrdersLoading = false;

  adminOrders: OrderTrack[] = [];
  adminOrdersLoading = false;
  adminFilterStatus = 'ALL';

  constructor(
    private orderTrackerService: OrderTrackerService,
    public authService: AuthService
  ) {}

  ngOnInit(): void {
    if (this.authService.isAdmin) {
      this.activeTab = 'admin-panel';
      this.loadAdminOrders();
    } else if (this.authService.isLoggedIn) {
      this.activeTab = 'my-orders';
      this.loadMyOrders();
    }
  }

  switchTab(tab: 'search' | 'my-orders' | 'admin-panel') {
    this.activeTab = tab;
    this.errorMessage = '';
    if (tab === 'my-orders') {
      this.loadMyOrders();
    } else if (tab === 'admin-panel') {
      this.loadAdminOrders();
    }
  }

  onTrackOrder() {
    if (!this.searchOrderId.trim()) {
      this.errorMessage = 'Please enter a valid Order ID (e.g. EK1001, EK1002, or EK1003)';
      return;
    }

    this.loading = true;
    this.errorMessage = '';
    this.orderData = null;

    this.orderTrackerService.trackOrder(this.searchOrderId.trim()).subscribe(res => {
      this.loading = false;
      if (res.success && res.data) {
        this.orderData = res.data;
      } else {
        this.errorMessage = res.message || 'Order ID not found.';
      }
    });
  }

  loadMyOrders() {
    const userEmail = this.authService.currentUserValue?.email;
    if (!userEmail) return;

    this.userOrdersLoading = true;
    this.orderTrackerService.getMyOrders(userEmail).subscribe(res => {
      this.userOrdersLoading = false;
      if (res.success && res.data) {
        this.userOrders = res.data;
      }
    });
  }

  loadAdminOrders() {
    this.adminOrdersLoading = true;
    this.orderTrackerService.getAllOrdersAdmin().subscribe(res => {
      this.adminOrdersLoading = false;
      if (res.success && res.data) {
        this.adminOrders = res.data;
      }
    });
  }

  updateOrderStatusAdmin(order: OrderTrack, newStatus: string) {
    this.orderTrackerService.updateOrderStatusAdmin(
      order.orderId,
      newStatus,
      order.carrier || 'eKart Express Logistics',
      order.trackingNumber || ('TRK-' + Math.floor(1000000 + Math.random() * 9000000))
    ).subscribe(res => {
      if (res.success && res.data) {
        order.status = res.data.status;
        order.carrier = res.data.carrier;
        order.trackingNumber = res.data.trackingNumber;
        alert(`Order ${order.orderId} updated to ${newStatus}!`);
      } else {
        alert(res.message || 'Failed to update order status.');
      }
    });
  }

  get filteredAdminOrders(): OrderTrack[] {
    if (this.adminFilterStatus === 'ALL') {
      return this.adminOrders;
    }
    return this.adminOrders.filter(o => o.status === this.adminFilterStatus);
  }

  isStepCompleted(step: string, targetOrder?: OrderTrack): boolean {
    const current = targetOrder ? targetOrder.status : this.orderData?.status;
    if (!current) return false;

    const rank: { [key: string]: number } = {
      'ORDER_RECEIVED': 1,
      'PROCESSING': 1,
      'ACCEPTED': 2,
      'SHIPPED': 3,
      'IN_TRANSIT': 3,
      'OUT_FOR_DELIVERY': 4,
      'DELIVERED': 5
    };

    const currentRank = rank[current] || 1;
    const stepRank = rank[step] || 1;

    return currentRank >= stepRank;
  }

  formatStatusBadge(status: string): string {
    switch (status) {
      case 'ORDER_RECEIVED': return '📌 Order Received';
      case 'ACCEPTED': return '🟢 Order Accepted';
      case 'SHIPPED': return '📦 Handed to Delivery Store';
      case 'OUT_FOR_DELIVERY': return '🛵 Out for Delivery to Home';
      case 'DELIVERED': return '✅ Delivered to Home';
      default: return status;
    }
  }
}
<div class="tracker-page">
  <div class="tracker-header">
    <h1>Real-Time <span class="highlight">Order Tracker</span></h1>
    <p>Track your shipment status from dispatch to delivery in real-time.</p>
  </div>

  <div class="search-card">
    <div class="search-form">
      <input type="text" [(ngModel)]="searchOrderId" placeholder="Enter Order ID (e.g. EK1001, EK1002, EK1003)..." class="search-input">
      <button (click)="onTrackOrder()" [disabled]="loading" class="btn btn-primary">
        {{ loading ? 'Searching...' : 'Track Order' }}
      </button>
    </div>
    <div class="sample-hints">
      Try sample order IDs: <span (click)="searchOrderId='EK1001'; onTrackOrder()" class="hint-badge">EK1001</span>, <span (click)="searchOrderId='EK1002'; onTrackOrder()" class="hint-badge">EK1002</span>, <span (click)="searchOrderId='EK1003'; onTrackOrder()" class="hint-badge">EK1003</span>
    </div>
  </div>

  <div class="alert alert-danger" *ngIf="errorMessage">
    ⚠️ {{ errorMessage }}
  </div>

  <!-- ORDER TRACKING DETAILS -->
  <div class="order-details-card" *ngIf="orderData">
    <div class="card-top-bar">
      <div>
        <h2>Order #{{ orderData.orderId }}</h2>
        <span class="tracking-no">Tracking #: {{ orderData.trackingNumber || 'TRK-9837412' }}</span>
      </div>
      <div class="status-pill" [class.delivered]="orderData.status === 'DELIVERED'">
        {{ orderData.status }}
      </div>
    </div>

    <!-- TIMELINE PROGRESS -->
    <div class="timeline">
      <div class="timeline-step" [class.completed]="isStepCompleted('PROCESSING')">
        <div class="step-circle">✓</div>
        <div class="step-info">
          <h5>Order Processed</h5>
          <p>Verified & packed</p>
        </div>
      </div>
      <div class="timeline-step" [class.completed]="isStepCompleted('SHIPPED')">
        <div class="step-circle">✓</div>
        <div class="step-info">
          <h5>Shipped</h5>
          <p>Handed to {{ orderData.carrier || 'Courier' }}</p>
        </div>
      </div>
      <div class="timeline-step" [class.completed]="isStepCompleted('IN_TRANSIT')">
        <div class="step-circle">✓</div>
        <div class="step-info">
          <h5>In Transit</h5>
          <p>On the way to hub</p>
        </div>
      </div>
      <div class="timeline-step" [class.completed]="isStepCompleted('DELIVERED')">
        <div class="step-circle">✓</div>
        <div class="step-info">
          <h5>Out for Delivery</h5>
          <p>Final destination</p>
        </div>
      </div>
    </div>

    <div class="details-grid">
      <div class="detail-item">
        <span class="label">Courier Partner</span>
        <span class="val">{{ orderData.carrier || 'BlueDart Express' }}</span>
      </div>
      <div class="detail-item">
        <span class="label">Estimated Delivery</span>
        <span class="val highlight-val">{{ orderData.estimatedDelivery || '2-3 Days' }}</span>
      </div>
      <div class="detail-item">
        <span class="label">Delivery Address</span>
        <span class="val">{{ orderData.shippingAddress }}</span>
      </div>
      <div class="detail-item">
        <span class="label">Total Amount</span>
        <span class="val">₹{{ orderData.totalAmount || 1299 }}</span>
      </div>
    </div>
  </div>
</div>
